package co.edu.uco.seguridad.pdp.authorization.infrastructure.adapter.primary.web.interactor.impl;
import co.edu.uco.seguridad.pdp.applications.application.rule.validator.ApplicationOwnerLookupValidator; import co.edu.uco.seguridad.pdp.authorization.application.primaryport.request.*; import co.edu.uco.seguridad.pdp.authorization.application.usecase.ReadApplicationSecuritySummaryUseCase; import co.edu.uco.seguridad.pdp.authorization.infrastructure.adapter.primary.web.dto.response.ApplicationSecuritySummaryWebResponse; import co.edu.uco.seguridad.pdp.authorization.infrastructure.adapter.primary.web.interactor.ReadApplicationSecuritySummaryInteractor; import co.edu.uco.seguridad.pdp.commons.model.*; import co.edu.uco.seguridad.pdp.identity.application.rule.validator.SubjectUserIdLookupValidator; import co.edu.uco.seguridad.shared.security.*; import co.edu.uco.seguridad.shared.web.RequestFieldParser; import reactor.core.publisher.Mono; import java.util.Set;
public final class ReadApplicationSecuritySummaryInteractorImpl implements ReadApplicationSecuritySummaryInteractor {private final ApplicationOwnerLookupValidator owner;private final SubjectUserIdLookupValidator identities;private final ReadApplicationSecuritySummaryUseCase useCase;public ReadApplicationSecuritySummaryInteractorImpl(ApplicationOwnerLookupValidator owner,SubjectUserIdLookupValidator identities,ReadApplicationSecuritySummaryUseCase useCase){this.owner=owner;this.identities=identities;this.useCase=useCase;}public Mono<ApplicationSecuritySummaryWebResponse> execute(String raw){ApplicationId app=RequestFieldParser.parse("applicationId",raw,ApplicationId::of);return SecurityContext.currentPrincipal().flatMap(p->user(p).flatMap(u->owner.execute(app).map(t->new AdministrationRequest(t,app,u,p.subject(),Set.of(),p.authenticationContext())))).flatMap(a->useCase.execute(new ReadApplicationSecuritySummaryRequest(a))).map(s->new ApplicationSecuritySummaryWebResponse(new ApplicationSecuritySummaryWebResponse.Application(s.application().id(),s.application().name(),s.application().description(),s.application().baseUrl()),new ApplicationSecuritySummaryWebResponse.Counts(s.counts().resources(),s.counts().roles(),s.counts().profiles(),s.counts().administrators(),s.counts().roleAssignments(),s.counts().profileAssignments())));}private Mono<UserId> user(PdpPrincipal p){return p.userId().map(Mono::just).orElseGet(()->identities.execute(p.subject()));}}
